const s = $('Settings').first().json;
const fromEmail = $('Document received by email').isExecuted;
const out = [];
$input.all().forEach((item, index) => {
  for (const [key, file] of Object.entries(item.binary || {})) {
    const mime = file.mimeType || '';
    const supported = mime === 'application/pdf' || /^image\/(png|jpe?g|webp)$/.test(mime);
    if (!supported) continue;
    // Skip small images in emails: usually logos and signatures, not receipts.
    const kb = Number(String(file.fileSize || '0').replace(/[^0-9.]/g, '')) * (/mb/i.test(String(file.fileSize)) ? 1024 : 1);
    if (fromEmail && mime.startsWith('image/') && kb && kb < Number(s.minImageKb)) continue;
    const from = fromEmail ? ((item.json.from && item.json.from.text) || item.json.from || '') : 'upload form';
    out.push({ json: { file_name: file.fileName || key, mime_type: mime, source: fromEmail ? 'email' : 'upload', received_from: String(from), email_subject: item.json.subject || '' },
      binary: { data: file }, pairedItem: { item: index } });
  }
});
return out;

function documentPart(mimeType, base64, fileName) {
  if (mimeType === "application/pdf") {
    return { type: "file", file: { filename: fileName || "document.pdf", file_data: `data:application/pdf;base64,${base64}` } };
  }
  if (/^image\/(png|jpe?g|webp|gif)$/.test(mimeType)) {
    return { type: "image_url", image_url: { url: `data:${mimeType};base64,${base64}` } };
  }
  return null;
}

function buildExtractRequest(part, s) {
  const system = [
    "You extract data from invoices, receipts and bills. Read the document carefully. Never guess: use null when a value is missing or unreadable.",
    "Dates as YYYY-MM-DD. Amounts as numbers with a dot for decimals, no currency symbols. Currency as a 3-letter ISO code.",
    'Answer with JSON only: {"document_type":"invoice|receipt|credit_note|other","supplier_name":"","supplier_vat_id":null,"customer_name":null,',
    '"invoice_number":null,"invoice_date":null,"due_date":null,"currency":null,"subtotal":null,"vat_amount":null,"total":null,',
    '"line_items":[{"description":"","quantity":null,"unit_price":null,"amount":null}],"confidence":"high|medium|low"}',
  ].join("\n");
  return {
    model: s.openAiModel,
    temperature: 0,
    response_format: { type: "json_object" },
    messages: [
      { role: "system", content: system },
      { role: "user", content: [{ type: "text", text: "Extract the data from this document." }, part] },
    ],
  };
}

const s = $('Settings').first().json;
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  const part = documentPart(items[i].json.mime_type, buffer.toString('base64'), items[i].json.file_name);
  items[i].json.request = buildExtractRequest(part, s);
  items[i].pairedItem = { item: i };
}
return items;

function readAiJson(response) {
  const content = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
  if (!content) throw new Error("OpenAI returned no answer: " + JSON.stringify(response).slice(0, 300));
  try {
    return JSON.parse(content);
  } catch {
    throw new Error("OpenAI answer was not valid JSON: " + content.slice(0, 300));
  }
}

function checkExtraction(x) {
  const issues = [];
  const num = (v) => (v === null || v === undefined || v === "" ? null : Number(v));
  const subtotal = num(x.subtotal);
  const vat = num(x.vat_amount);
  const total = num(x.total);
  if (!x.supplier_name) issues.push("supplier missing");
  if (!x.invoice_date || !/^\d{4}-\d{2}-\d{2}$/.test(x.invoice_date)) issues.push("date missing");
  if (total === null || Number.isNaN(total)) issues.push("total missing");
  if (!x.currency) issues.push("currency missing");
  if (subtotal !== null && vat !== null && total !== null && Math.abs(subtotal + vat - total) > 0.02) {
    issues.push(`subtotal + VAT (${(subtotal + vat).toFixed(2)}) does not match total (${total.toFixed(2)})`);
  }
  const lines = Array.isArray(x.line_items) ? x.line_items : [];
  const lineSum = lines.reduce((sum, l) => sum + (Number(l.amount) || 0), 0);
  if (lines.length && subtotal !== null && Math.abs(lineSum - subtotal) > 0.05 && Math.abs(lineSum - (total || 0)) > 0.05) {
    issues.push("line items do not add up");
  }
  if (x.confidence === "low") issues.push("low confidence reading");
  return { status: issues.length ? "needs review" : "ok", issues: issues.join("; ") };
}

function documentFileName(x, originalName) {
  const clean = (v) => String(v || "").normalize("NFKD").replace(/[^\w.-]+/g, "-").replace(/-+/g, "-").replace(/^-|-$/g, "").slice(0, 40);
  const ext = (String(originalName || "").match(/\.[a-z0-9]{2,5}$/i) || [".pdf"])[0].toLowerCase();
  return [clean(x.invoice_date) || "undated", clean(x.supplier_name) || "unknown-supplier", clean(x.invoice_number) || "no-number"].join("_") + ext;
}

const prepared = $('Prepare extraction').all();
return $input.all().map((item, i) => {
  const src = prepared[i];
  let x;
  try { x = readAiJson(item.json); } catch (e) { x = { confidence: 'low', error: e.message }; }
  const check = checkExtraction(x);
  return {
    json: {
      processed_at: new Date().toISOString(), source: src.json.source, received_from: src.json.received_from, original_file: src.json.file_name,
      document_type: x.document_type || '', supplier_name: x.supplier_name || '', supplier_vat_id: x.supplier_vat_id || '',
      invoice_number: x.invoice_number || '', invoice_date: x.invoice_date || '', due_date: x.due_date || '', currency: x.currency || '',
      subtotal: x.subtotal ?? '', vat_amount: x.vat_amount ?? '', total: x.total ?? '',
      line_items: JSON.stringify(x.line_items || []), status: check.status, issues: check.issues,
      drive_name: documentFileName(x, src.json.file_name),
    },
    binary: src.binary,
    pairedItem: { item: i },
  };
});

const rows = $('Check the data').all();
return $input.all().map((item, i) => {
  const { drive_name, ...data } = rows[i].json;
  return { json: { ...data, drive_file: drive_name, drive_link: item.json.webViewLink || ('https://drive.google.com/file/d/' + item.json.id + '/view') }, pairedItem: { item: i } };
});

